// Copies the phone map's libraries (Leaflet, MapLibre, the Leaflet–MapLibre bridge) and the
// Barlow Condensed font into frontend/components/map/vendor.js, so the phone map needs no
// download site. Re-run after upgrading leaflet / maplibre-gl: npm run map:vendor
import { readFile, writeFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);
const read = path => readFile(new URL(path, root), 'utf8');
const safe = text => text.replace(/<\/(script|style)/gi, '<\\/$1').replace(/\/\/# sourceMappingURL=.*$/gm, '');
const font = async file => (await readFile(new URL(`frontend/assets/fonts/${file}`, root))).toString('base64');
const version = async pkg => JSON.parse(await read(`node_modules/${pkg}/package.json`)).version;

const parts = {
  VERSIONS: `leaflet ${await version('leaflet')}, maplibre-gl ${await version('maplibre-gl')}, @maplibre/maplibre-gl-leaflet ${await version('@maplibre/maplibre-gl-leaflet')}`,
  LEAFLET_CSS: safe(await read('node_modules/leaflet/dist/leaflet.css')),
  MAPLIBRE_CSS: safe(await read('node_modules/maplibre-gl/dist/maplibre-gl.css')),
  LEAFLET_JS: safe(await read('node_modules/leaflet/dist/leaflet.js')),
  MAPLIBRE_JS: safe(await read('node_modules/maplibre-gl/dist/maplibre-gl.js')),
  BRIDGE_JS: safe(await read('node_modules/@maplibre/maplibre-gl-leaflet/leaflet-maplibre-gl.js')),
  FONT_CSS: `@font-face{font-family:'Barlow Condensed';font-weight:500;src:url(data:font/ttf;base64,${await font('BarlowCondensed_500Medium.ttf')}) format('truetype');}` +
            `@font-face{font-family:'Barlow Condensed';font-weight:600;src:url(data:font/ttf;base64,${await font('BarlowCondensed_600SemiBold.ttf')}) format('truetype');}`,
};
const body = Object.entries(parts).map(([name, value]) => `export const ${name} = ${JSON.stringify(value)};`).join('\n');
await writeFile(new URL('frontend/components/map/vendor.js', root),
  `// Generated by scripts/vendor-map.mjs. Do not edit; run npm run map:vendor instead.\n// Leaflet (BSD-2-Clause), MapLibre GL JS (BSD-3-Clause), Barlow Condensed (OFL 1.1).\n${body}\n`);
console.log(`Wrote frontend/components/map/vendor.js (${parts.VERSIONS})`);
